Design a 4-bit binary counter that increments the count on each clock cycle, with a reset functionality. Upon reset, the counter initializes to zero. The counter operates in three states: IDLE, where it starts counting from zero; COUNTING, where it increments the count until it reaches the value of 9 (1001 in binary); and RESET, where it sets the count back to 9 before transitioning back to the IDLE state. The inclusion of state transitions allows for controlled counting behavior while ensuring proper reset functionality.
module top_module(
  input clk,
  input reset,
  output reg [3:0] count
);

code:
module top_module(
  input clk,
  input reset,
  output reg [3:0] count
);parameter IDLE = 2'b00, COUNTING = 2'b01, RESET = 2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= RESET;
      count <= 4'b0;
    end
    else begin
      state <= next_state;
      case (state)
        IDLE: begin
          count <= 4'b0;
          if (count == 4'b1001) next_state <= RESET;
          else next_state <= COUNTING;
        end
        COUNTING: begin
          count <= count + 1;
          if (count == 4'b1001) next_state <= RESET;
          else next_state <= COUNTING;
        end
        RESET: begin
          count <= 4'b1001;
          next_state <= IDLE;
        end
      endcase
    end
  end
endmodule

