module counter3bit_up (
    input clk,
    input rst,
    input en,
    output [2:0] q
);

    reg [2:0] q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q_reg <= 3'b000;
        else if (en)
            q_reg <= q_reg + 1;
    end

