        reg1 <= D;
        reg2 <= reg1;
        reg3 <= reg2;
        reg4 <= reg3;
    end else begin
        reg1 <= reg2;
        reg2 <= reg3;
        reg3 <= reg4;
        reg4 <= OUT;
    end
end

assign OUT = reg4;

endmodule

