description:
Implement the Verilog module based on the following description.
Build an 8-bit register with synchronous active low reset signal and a load signal. When the load signal is high, the register loads the input data.
// (1) reset_n: Resets the register to 8'b00000000 when low.
// (2) load: Enables the loading of input data when high.
// (3) data_in: The input data to be loaded into the register.
// (4) q: The value of the register.

module top_module(
    input clk,
    input reset_n,
    input load,
    input [7:0] data_in,
    output reg [7:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input load,
    input [7:0] data_in,
    output reg [7:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the register to 8'b00000000
            q <= 8'b00000000;
        end else if (load) begin
            // Load operation: Load data_in into the register when load is high
            q <= data_in;
        end
    end

endmodule

