description:
Design a configurable up/down counter module with a width of 11 bits, capable of counting within specified limits. The counter increments or decrements based on a 2-bit input signal, `count_up`, with two modes: counting up by 2 when `count_up` is 10, or counting down by 2 when `count_up` is 01. The counter has a reset functionality to clear its value, and it operates only when enabled. The counting operation is constrained by defined limits to prevent overflow or underflow, with the upper limit set to 800 minus the defined board width of 80. This module is particularly suited for applications requiring controlled counting in digital systems.
module top_module(
	input clk, enable, reset,
	 input [1:0] count_up,
	output reg [WIDTH-1:0] count
);

code:
module top_module(
	input clk, enable, reset,
	 input [1:0] count_up,
	output reg [WIDTH-1:0] count
);parameter WIDTH = 11;
	parameter board_width=80;
    parameter x_total=800;

	reg [WIDTH-1:0] direction;
	reg [WIDTH-1:0] limit;


	always @ (posedge clk or posedge reset)
	begin
		if (reset)
			count <= 0;
		else if (enable == 1'b1)
		begin
			if (count_up==2'b10)
			begin
				direction <= 2;
				limit <= x_total-board_width;	 
			end
			else 
			begin
			if (count_up==2'b01)
			     begin
				direction <= -2; 
				limit <= {WIDTH{1'b0}};
				end
			else
			    direction <= 0;
			end

			if (count != limit)
				count <= count + direction;
		end
	end

endmodule

