module top_module(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    input clk,          // Add clk input
    output reg [3:0] Q  // Change Q to output reg
);reg [3:0] sum;
reg [3:0] diff;
reg [3:0] A_reg;
reg [3:0] B_reg;
reg SUB_reg;

always @(posedge clk) begin
    A_reg <= A;
    B_reg <= B;
    SUB_reg <= SUB;
end

always @(posedge clk) begin
    if (SUB_reg == 0) begin
        sum <= A_reg + B_reg;
    end else begin
        diff <= A_reg - B_reg;
    end
end

always @(posedge clk) begin
    if (SUB_reg == 0) begin
        Q <= sum;
    end else begin
        Q <= diff;
    end
end

endmodule

