module top_module(
    input clk,
    input reset,
    input enable,
    output reg red,
    output reg yellow,
    output reg green
);reg [5:0] count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            red <= 0;
            yellow <= 0;
            green <= 1;
        end else if (enable) begin
            count <= count + 1;
            case (count)
                0: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                end
                20: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
                22: begin
                    red <= 1;
                    yellow <= 1;
                    green <= 0;
                end
                24: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;
                end
                44: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                    count <= 0;
                end
            endcase
        end
    end

endmodule

